GRUPS = ["CD"] * 30 + ["CD+CI"] * 20 + ["pronoms febles"] * 15 + ["predicat nominal"] * 25 + ["veu passiva"] * 20 + \
        ["impersonal"] * 15 + ["CPRED"] * 15 + ["CRV"] * 15 + ["CC"] * 50 + ["verbs incoatius"] * 25 + ["subjecte el·líptic"] * 20


def analisi(subj, ns, nv, comps, op):
    return {"subjecte": {"text": subj, "nucli": ns, "eliptic": subj is None and "i" not in op},
            "predicat": {"tipus": "nominal" if "n" in op else "verbal", "nucli": nv,
                         "complements": [{"funcio": f, "text": t} for f, t in comps]},
            "veu": "passiva" if "p" in op else "activa", "impersonal": "i" in op}


EVAL = [{"frase": f, "ref": analisi(s, ns, nv, c, op), "grup": g} for (f, s, ns, nv, c, op), g in zip(D, GRUPS)]

if __name__ == "__main__":
    import sys
    sys.path.insert(0, ".")
    from common import valida, norm, REFERENCIA
    assert len(D) == 250 == len(GRUPS), (len(D), len(GRUPS))
    dolentes = [(r["frase"], valida(r["frase"], r["ref"])[1]) for r in EVAL if not valida(r["frase"], r["ref"])[0]]
    print("invàlides:", dolentes)
    fr = [norm(r["frase"]) for r in EVAL]
    print("repetides:", len(fr) - len(set(fr)), "· a la referència de 30:", len(set(fr) & {norm(f) for f, _ in REFERENCIA}))
    with open("resultats/eval250.jsonl", "w", encoding="utf-8") as f:
        for r in EVAL: f.write(json.dumps(r, ensure_ascii=False) + "\n")
    from collections import Counter
    print(Counter(g for g in GRUPS)); print(Counter(c["funcio"] for r in EVAL for c in r["ref"]["predicat"]["complements"]))
